    def generate_d_regular_graph(d, n):
        if d * (n - 1) % 2 != 0:
            return None
        graph = {i: set() for i in range(n)}
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                if len(graph[i]) < d and len(graph[j]) < d:
                    graph[i].add(j)
                    graph[j].add(i)
                    edges.append((i, j))
        return graph

    def tseitin_formula(graph):
        literals = {node: f'x{node}' for node in range(len(graph))}
        clauses = []
        for node, neighbors in graph.items():
            clause = [f'-{literals[node]}']
            for neighbor in neighbors:
                clause.append(literals[neighbor])
            clauses.append(clause)
            for i in range(len(neighbors)):
                for j in range(i + 1, len(neighbors)):
                    clauses.append([f'-{literals[neighbors[i]]}', f'-{literals[neighbors[j]]}', literals[node]])
        return clauses

    def gaussian_elimination(matrix):
        n = len(matrix)
        m = len(matrix[0])
        for i in range(n):
            if matrix[i][i] == 0:
                for j in range(i + 1, n):
                    if matrix[j][i] != 0:
                        matrix[i], matrix[j] = matrix[j], matrix[i]
                        break
                else:
                    return None
            pivot = Fraction(matrix[i][i])
            for j in range(m):
